pub fn vanilla_block_entity_type(type_id: i32) -> Option<&'static BlockEntityTypeCatalogEntry> {
    VANILLA_BLOCK_ENTITY_TYPES.get(usize::try_from(type_id).ok()?)
}

pub fn vanilla_block_entity_type_for_resource_id(
    resource_id: &str,
) -> Option<&'static BlockEntityTypeCatalogEntry> {
    let path = resource_id
        .strip_prefix("minecraft:")
        .unwrap_or(resource_id);
    if path.is_empty() || path.contains(':') {
        return None;
    }
    VANILLA_BLOCK_ENTITY_TYPES
        .iter()
        .find(|entry| entry.resource_id.strip_prefix("minecraft:") == Some(path))
}

pub fn vanilla_block_entity_type_id_for_resource_id(resource_id: &str) -> Option<i32> {
    Some(vanilla_block_entity_type_for_resource_id(resource_id)?.id)
}

pub fn vanilla_block_entity_resource_id_for_type_id(type_id: i32) -> Option<&'static str> {
    Some(vanilla_block_entity_type(type_id)?.resource_id)
}

pub fn vanilla_block_entity_type_only_op_can_set_nbt(type_id: i32) -> bool {
    vanilla_block_entity_type(type_id)
        .map(|entry| entry.only_op_can_set_nbt)
        .unwrap_or(false)
}

pub fn vanilla_block_entity_type_provides_menu(type_id: i32) -> bool {
    vanilla_block_entity_type(type_id)
        .map(|entry| entry.provides_menu)
        .unwrap_or(false)
}

#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn block_entity_type_catalog_is_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_BLOCK_ENTITY_TYPES.len(), 49);
        let mut constant_names = HashSet::new();
        let mut resource_ids = HashSet::new();
        for (id, entry) in VANILLA_BLOCK_ENTITY_TYPES.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(constant_names.insert(entry.constant_name));
            assert!(resource_ids.insert(entry.resource_id));
            assert!(entry.resource_id.starts_with("minecraft:"));
        }
        assert_eq!(
            VANILLA_BLOCK_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.only_op_can_set_nbt)
                .count(),
            6
        );
    }

    #[test]
    fn menu_provider_block_entity_types_come_from_generated_metadata() {
        assert_eq!(
            VANILLA_BLOCK_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.provides_menu)
                .count(),
            14
        );
        for type_id in [
            VANILLA_BLOCK_ENTITY_TYPE_FURNACE_ID,
            VANILLA_BLOCK_ENTITY_TYPE_CHEST_ID,
            VANILLA_BLOCK_ENTITY_TYPE_TRAPPED_CHEST_ID,
            VANILLA_BLOCK_ENTITY_TYPE_BARREL_ID,
            VANILLA_BLOCK_ENTITY_TYPE_HOPPER_ID,
            VANILLA_BLOCK_ENTITY_TYPE_LECTERN_ID,
            VANILLA_BLOCK_ENTITY_TYPE_CRAFTER_ID,
        ] {
            assert!(vanilla_block_entity_type_provides_menu(type_id));
        }
        assert!(!vanilla_block_entity_type_provides_menu(
            VANILLA_BLOCK_ENTITY_TYPE_SIGN_ID
        ));
        assert!(!vanilla_block_entity_type_provides_menu(
            VANILLA_BLOCK_ENTITY_TYPE_BELL_ID
        ));
        assert!(!vanilla_block_entity_type_provides_menu(-1));
    }

    #[test]
    fn operator_only_custom_data_comes_from_generated_block_entity_metadata() {
        assert!(vanilla_block_entity_type_only_op_can_set_nbt(
            VANILLA_BLOCK_ENTITY_TYPE_COMMAND_BLOCK_ID
        ));
        assert!(vanilla_block_entity_type_only_op_can_set_nbt(
            VANILLA_BLOCK_ENTITY_TYPE_LECTERN_ID
        ));
        assert!(vanilla_block_entity_type_only_op_can_set_nbt(
            VANILLA_BLOCK_ENTITY_TYPE_SIGN_ID
        ));
        assert!(vanilla_block_entity_type_only_op_can_set_nbt(
            VANILLA_BLOCK_ENTITY_TYPE_HANGING_SIGN_ID
        ));
        assert!(vanilla_block_entity_type_only_op_can_set_nbt(
            VANILLA_BLOCK_ENTITY_TYPE_MOB_SPAWNER_ID
        ));
        assert!(vanilla_block_entity_type_only_op_can_set_nbt(
            VANILLA_BLOCK_ENTITY_TYPE_TRIAL_SPAWNER_ID
        ));
        assert!(!vanilla_block_entity_type_only_op_can_set_nbt(
            VANILLA_BLOCK_ENTITY_TYPE_CHEST_ID
        ));
        assert!(!vanilla_block_entity_type_only_op_can_set_nbt(-1));
    }

    fn starts_with_integer_literal(value: &str) -> bool {
        let mut characters = value.chars();
        let Some(first) = characters.next() else {
            return false;
        };
        first.is_ascii_digit()
            || (first == '-'
                && characters
                    .next()
                    .is_some_and(|character| character.is_ascii_digit()))
    }

    fn contains_numeric_block_entity_type_id_reference(source: &str) -> bool {
        let compact: String = source
            .chars()
            .filter(|character| !character.is_whitespace())
            .collect();
        let numeric_construction =
            compact
                .match_indices("block_entity_type_id:")
                .any(|(offset, _)| {
                    let boundary = offset == 0
                        || compact[..offset]
                            .chars()
                            .next_back()
                            .is_some_and(|character| {
                                !character.is_ascii_alphanumeric() && character != '_'
                            });
                    boundary
                        && starts_with_integer_literal(
                            &compact[offset + "block_entity_type_id:".len()..],
                        )
                });
        let numeric_field_reference =
            compact
                .match_indices(".block_entity_type_id")
                .any(|(offset, _)| {
                    let suffix = &compact[offset + ".block_entity_type_id".len()..];
                    [",", "==", "!=", "="].iter().any(|separator| {
                        suffix
                            .strip_prefix(separator)
                            .is_some_and(starts_with_integer_literal)
                    })
                });
        let numeric_component_construction = compact
            .match_indices("block_entity_data_type_id:Some(")
            .any(|(offset, _)| {
                starts_with_integer_literal(
                    &compact[offset + "block_entity_data_type_id:Some(".len()..],
                )
            });
        let numeric_component_reference =
            compact
                .match_indices(".block_entity_data_type_id")
                .any(|(offset, _)| {
                    let suffix = &compact[offset + ".block_entity_data_type_id".len()..];
                    [",Some(", "==Some(", "!=Some(", "=Some("]
                        .iter()
                        .any(|separator| {
                            suffix
                                .strip_prefix(separator)
                                .is_some_and(starts_with_integer_literal)
                        })
                });
        numeric_construction
            || numeric_field_reference
            || numeric_component_construction
            || numeric_component_reference
    }

    #[test]
    fn numeric_block_entity_type_id_guard_covers_construction_and_comparison() {
        assert!(contains_numeric_block_entity_type_id_reference(
            "block_entity_type_id: 7,"
        ));
        assert!(contains_numeric_block_entity_type_id_reference(
            "assert_eq!(entry.block_entity_type_id,\n 45);"
        ));
        assert!(contains_numeric_block_entity_type_id_reference(
            "block_entity_data_type_id: Some(23),"
        ));
        assert!(contains_numeric_block_entity_type_id_reference(
            "patch.block_entity_data_type_id = Some(9);"
        ));
        assert!(contains_numeric_block_entity_type_id_reference(
            "assert_eq!(patch.block_entity_data_type_id, Some(0));"
        ));
        assert!(!contains_numeric_block_entity_type_id_reference(
            "entity_type_id: 7,"
        ));
        assert!(!contains_numeric_block_entity_type_id_reference(
            "block_entity_type_id: VANILLA_BLOCK_ENTITY_TYPE_SIGN_ID,"
        ));
        assert!(!contains_numeric_block_entity_type_id_reference(
            "block_entity_data_type_id: Some(VANILLA_BLOCK_ENTITY_TYPE_COMMAND_BLOCK_ID),"
        ));
    }

    #[test]
    fn semantic_sources_do_not_restore_numeric_block_entity_type_ids() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if contains_numeric_block_entity_type_id_reference(&source) {
                    violations.push(format!(
                        "{}: numeric block-entity-type id reference",
                        path.display()
                    ));
                }
            }
        }
        let mut violations = Vec::new();
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        for directory in [
            "bbb-native/src",
            "bbb-world/src",
            "bbb-net/src",
            "bbb-item-model/src",
            "bbb-renderer/src",
        ] {
            visit(&crates.join(directory), &mut violations);
        }
        assert!(
            violations.is_empty(),
            "semantic consumers restored numeric block-entity-type ids:\n{}",
            violations.join("\n")
        );
    }

    #[test]
    fn block_entity_type_catalog_preserves_vanilla_order_and_compatibility_api() {
        assert_eq!(
            vanilla_block_entity_resource_id_for_type_id(0),
            Some("minecraft:furnace")
        );
        assert_eq!(
            vanilla_block_entity_resource_id_for_type_id(9),
            Some("minecraft:mob_spawner")
        );
        assert_eq!(
            vanilla_block_entity_resource_id_for_type_id(45),
            Some("minecraft:vault")
        );
        assert_eq!(VANILLA_BLOCK_ENTITY_TYPE_VAULT_ID, 45);
        assert_eq!(
            vanilla_block_entity_type_id_for_resource_id("minecraft:mob_spawner"),
            Some(VANILLA_BLOCK_ENTITY_TYPE_MOB_SPAWNER_ID)
        );
        assert_eq!(
            vanilla_block_entity_type_id_for_resource_id("vault"),
            Some(VANILLA_BLOCK_ENTITY_TYPE_VAULT_ID)
        );
        assert_eq!(
            vanilla_block_entity_type_id_for_resource_id("example:vault"),
            None
        );
        assert_eq!(
            vanilla_block_entity_resource_id_for_type_id(48),
            Some("minecraft:copper_golem_statue")
        );
        assert_eq!(vanilla_block_entity_resource_id_for_type_id(-1), None);
        assert_eq!(vanilla_block_entity_resource_id_for_type_id(49), None);
    }
}
